with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"anish-sood","tag":"a dreamy, cross-cultural melange","u":"https://mixmag.net/feature/anyasa-anjunadeep-anjunabeats-goa-india-traditional-interview"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;